css:
/* Shared Teravera geometry, with appearance-specific surfaces. */
:root:not(.dark) { --tv-canvas: #f7f8fa; --tv-panel: #fff; --tv-border: #dfe4ed; --tv-bubble-border: #d8e3fb; --tv-link: #0236ad; --tv-shadow: rgba(2,54,173,.055); --tv-side-hover: #285bc6; }
:root.dark { --tv-canvas: #0b1426; --tv-panel: #111e36; --tv-border: #2a3a55; --tv-bubble-border: #2b4a76; --tv-link: #a9c9ff; --tv-shadow: rgba(0,0,0,.16); --tv-side-hover: #244b87; }
[data-chat-header] { background: var(--tv-panel) !important; border-bottom: 1px solid var(--tv-border) !important; }
[data-workspace-area="conversation"] { background: var(--tv-canvas) !important; }
[data-slot="composer-host"] { background: var(--tv-panel) !important; border: 1px solid var(--tv-border) !important; border-radius: 12px !important; box-shadow: 0 4px 18px var(--tv-shadow) !important; }
[data-user-message-bubble] { border: 1px solid var(--tv-bubble-border) !important; border-radius: 12px !important; }
[data-thread-details-card], [data-slot="settings-group"] { border: 1px solid var(--tv-border) !important; border-radius: 10px !important; box-shadow: none !important; }
.chat-markdown a { color: var(--tv-link); text-underline-offset: 3px; }
[data-slot="sidebar"], [data-slot="sidebar-inner"] { --foreground: #fff; --muted-foreground: #c3d3f5; --secondary-foreground: #fff; --accent-foreground: #fff; color: #fff !important; }
[data-slot="sidebar"] :is(a,button,span,p,h1,h2,h3,input,svg), [data-slot="sidebar-inner"] :is(a,button,span,p,h1,h2,h3,input,svg) { color: #fff !important; }
[data-slot="sidebar"] :is(small,time), [data-slot="sidebar-inner"] :is(small,time), [data-slot="sidebar"] input::placeholder { color: #c3d3f5 !important; }
[data-slot="sidebar"] [data-thread-item] { border-radius: 7px !important; }
[data-slot="sidebar"] [data-slot="project-monogram"] { color: #fff !important; background: var(--tv-side-hover) !important; }
[data-slot="sidebar"] svg.lucide { stroke-width: 1.7; }
/* A compact signature, aligned past the sidebar collapse control. */
[data-slot="sidebar-inner"]::before { content: ""; display: block; flex: 0 0 44px; min-height: 44px; width: 100%; box-sizing: border-box; background-image: url("data:image/svg+xml;base64,"); background-repeat: no-repeat; background-position: 52px center; background-size: 120px auto; pointer-events: none; }
